def context_tool_definitions(
    api_targets: tuple[str, ...] = (),
    new_paths: tuple[str, ...] = (),
    *,
    direct_reads: bool = False,
    map_navigation: bool = False,
) -> tuple[ModelToolDefinition, ...]:
