    descriptors: tuple[ToolDescriptor, ...] = _DEFINITIONS
    if map_navigation:
        descriptors = (
            *tuple(
                _schema(
                    "expand_source",
                    {
                        "unit": _TEXT,
                        "to": {
                            "type": "string",
                            "enum": ["file", "class", "symbol", "source"],
                        },
                    },
                )
                if d.name == "expand_source"
                else d
                for d in descriptors
            ),
            _schema(
                "repository_map",
